//! Unique original UI hard checks/C1 and C2 root ordering. Data only.
use std::{collections::HashSet};
use crate::{dm::dx::Proc,key_policy_control::{self as kc,Control},ui_actions_hosts::{Hosts,Acts},ui_actions_normalizer::Normaliser};
pub(crate) struct Checks<'a>{pub(crate) hosts:&'a Hosts,pub(crate) norm:&'a Normaliser,pub(crate) acts:&'a Acts}
impl Checks<'_>{
 pub(crate) fn check<C:Control>(&self,c:&mut C)->Result<Vec<(String,usize,String)>,C::Error>{let mut problems=Vec::new();for(interface,types)in self.hosts.by_interface_using(c)?{c.checkpoint()?;let mut legacy=false;for ty in &types{if self.hosts.is_legacy_using(ty,c)?{legacy=true;break}}if legacy{continue}let mut migrated=Vec::new();for ty in &types{if self.hosts.is_migrated_using(ty,c)?{kc::row(c,&mut migrated)?;migrated.push(ty);}}kc::sort_data(&mut migrated,&mut|a,b|->Result<std::cmp::Ordering,C::Error>{c.checkpoint()?;Ok(a.cmp(b))})?;if migrated.is_empty(){continue}let mut bytes=0usize;for ty in &migrated{c.checkpoint()?;bytes=bytes.checked_add(ty.len()).and_then(|n|n.checked_add(2)).ok_or_else(||c.overflow())?;}kc::reserve(c,||bytes.checked_add(64)?.checked_add(migrated.len().checked_mul(std::mem::size_of::<&str>())?))?;let where_=migrated.iter().map(|s|s.as_str()).collect::<Vec<_>>().join(", ");
  for call in self.acts.for_interface_using(Some(&interface),c)?{c.checkpoint()?;let(rel,line,raw_action)=(&call.rel,call.line,&call.raw_action);let Some(action)=&call.nkey else{let message=kc::format(c,format_args!("act('{}'): the dispatcher rejects this action name ([A-Za-z0-9_-], 64 max)",raw_action))?;problem(&mut problems,rel,line,message,c)?;continue};let mut answering=Vec::new();for ty in &migrated{c.checkpoint()?;if self.hosts.actions_of_using(ty,c)?.contains_key(action){kc::row(c,&mut answering)?;answering.push(*ty);}}if answering.is_empty(){let message=kc::format(c,format_args!("act('{}') has no act_{} on {}",raw_action,action,where_))?;problem(&mut problems,rel,line,message,c)?;continue}let raw_keys=call.raw_keys.as_deref().unwrap_or(&[]);let keys=call.nkeys.as_deref().unwrap_or(&[]);for(raw_key,key)in raw_keys.iter().zip(keys){c.checkpoint()?;match key{None=>{let message=kc::format(c,format_args!("act('{}') key '{}' is rejected by the dispatcher (dropped)",raw_action,raw_key))?;problem(&mut problems,rel,line,message,c)?;},Some(key)if self.norm.reserved.contains(key)=>{let message=kc::format(c,format_args!("act('{}') key '{}' is a reserved argument name (dropped)",raw_action,raw_key))?;problem(&mut problems,rel,line,message,c)?;},Some(key)=>{let mut seen=Vec::new();for ty in &answering{c.checkpoint()?;let p=self.hosts.actions_of_using(ty,c)?[action];let mut contains=false;for old in &seen{c.checkpoint()?;if *old==p{contains=true;break}}if !contains{kc::row(c,&mut seen)?;seen.push(p);}}for p in seen{c.checkpoint()?;let proc=&self.hosts.procs[p];let mut declared=false;for param in &proc.params{c.checkpoint()?;if param==key{declared=true;break}}if !declared{let message=kc::format(c,format_args!("act('{}') passes {}, which act_{} on {} doesn't declare",raw_action,key,action,proc.path))?;problem(&mut problems,rel,line,message,c)?;}}}}}
  }
 }Ok(problems)}
 pub(crate) fn ui_procs<C:Control>(&self,c:&mut C)->Result<Vec<usize>,C::Error>{let mut out=Vec::new();for(path,actions)in self.hosts.acts.iter(){c.checkpoint()?;if self.hosts.is_legacy_using(path,c)?{continue}let served=self.hosts.served_interfaces_using(path,c)?;if matches!(&served,Some(s)if s.is_empty()){continue}for(_,p)in actions.iter(){kc::row(c,&mut out)?;out.push(*p);}}for(_,actions)in self.hosts.cap_acts.iter(){c.checkpoint()?;for(_,p)in actions.iter(){kc::row(c,&mut out)?;out.push(*p);}}Ok(out)}
 pub(crate) fn unsent_params<C:Control>(&self,procs:&[usize],c:&mut C)->Result<Vec<(usize,String)>,C::Error>{let mut out=Vec::new();for &n in procs{c.checkpoint()?;let proc=&self.hosts.procs[n];let action=&proc.name[4..];let served=self.hosts.served_interfaces_using(&proc.path,c)?;if matches!(&served,Some(s)if s.is_empty()){continue}let mut sent:HashSet<Option<String>>=HashSet::new();let mut anything=false;let mut interfaces=Vec::new();match &served{None=>{kc::row(c,&mut interfaces)?;interfaces.push(None)},Some(values)=>for value in values{kc::row(c,&mut interfaces)?;interfaces.push(Some(crate::ui_actions_policy::own_using(c,value)?));}}
  for interface in interfaces{c.checkpoint()?;for call in self.acts.for_interface_using(interface.as_deref(),c)?{c.checkpoint()?;if call.nkey.as_deref()!=Some(action){continue}match &call.nkeys{None=>anything=true,Some(keys)=>for key in keys{c.checkpoint()?;if !sent.contains(key){crate::ui_actions_policy::set_room_using(&mut sent,c)?;let key=match key{Some(value)=>Some(crate::ui_actions_policy::own_using(c,value)?),None=>None};sent.insert(key);}}}}}if anything{continue}for param in &proc.params{c.checkpoint()?;if !self.norm.reserved.contains(param){let mut present=false;for key in &sent{c.checkpoint()?;if key.as_deref()==Some(param.as_str()){present=true;break}}if !present{kc::row(c,&mut out)?;out.push((n,crate::ui_actions_policy::own_using(c,param)?));}}}
 }Ok(out)}
 pub(crate) fn unvalidated_params<C:Control>(&self,procs:&[usize],c:&mut C,root:&mut dyn FnMut(usize,&Proc,&str,&mut C)->Result<Option<usize>,C::Error>)->Result<Vec<(usize,String,usize)>,C::Error>{let mut out=Vec::new();for &n in procs{c.checkpoint()?;let proc=&self.hosts.procs[n];for param in &proc.params{c.checkpoint()?;if self.norm.reserved.contains(param){continue}if let Some(line)=root(n,proc,param,c)?{kc::row(c,&mut out)?;out.push((n,crate::ui_actions_policy::own_using(c,param)?,line));}}}Ok(out)}
}
fn problem<C:Control>(out:&mut Vec<(String,usize,String)>,rel:&str,line:usize,message:String,c:&mut C)->Result<(),C::Error>{kc::row(c,out)?;out.push((crate::ui_actions_policy::own_using(c,rel)?,line,message));Ok(())}
